import { createHmac, timingSafeEqual } from "node:crypto";

const RELAY_STATE_MAX_AGE_MS = 60 * 60 * 1000;

export interface RelayInstallPayload {
  instanceUrl: string;
  userId: string;
  ts: number;
}

function canonicalPayloadJson(p: RelayInstallPayload): string {
  return JSON.stringify({ instanceUrl: p.instanceUrl, userId: p.userId, ts: p.ts });
}

/** Must stay in sync with VersionGate engine `src/utils/github-install-state.ts`. */
export function parseRelayInstallState(state: string | undefined, secret: string): RelayInstallPayload | null {
  if (!state || !secret) return null;
  try {
    const raw = Buffer.from(state, "base64url").toString("utf8");
    const o = JSON.parse(raw) as { p?: RelayInstallPayload; sig?: string };
    if (!o.p || typeof o.sig !== "string") return null;
    const body = canonicalPayloadJson(o.p);
    const expected = createHmac("sha256", secret).update(body, "utf8").digest("hex");
    const a = Buffer.from(o.sig, "hex");
    const b = Buffer.from(expected, "hex");
    if (a.length !== b.length || !timingSafeEqual(a, b)) return null;
    if (Date.now() - o.p.ts > RELAY_STATE_MAX_AGE_MS) return null;
    return o.p;
  } catch {
    return null;
  }
}

import { NextRequest, NextResponse } from "next/server";
import { parseRelayInstallState } from "@/lib/github-install-state";

function badRequest(message: string) {
  const body = `<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"/><title>GitHub relay error</title></head><body><p>${escapeHtml(message)}</p></body></html>`;
  return new NextResponse(body, {
    status: 400,
    headers: { "Content-Type": "text/html; charset=utf-8" },
  });
}

function escapeHtml(s: string) {
  return s
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

function isValidInstanceUrl(instanceUrl: string): boolean {
  const t = instanceUrl.trim();
  if (!t) return false;
  try {
    const u = new URL(t);
    if (u.protocol !== "http:" && u.protocol !== "https:") return false;
    if (!u.hostname) return false;
    return true;
  } catch {
    return false;
  }
}

/**
 * GitHub App install relay for self-hosted VersionGate instances.
 * GitHub App callback URL (fixed): https://versiongate.tech/api/github/callback
 */
export async function GET(request: NextRequest) {
  const secret = process.env.RELAY_SECRET;
  if (!secret) {
    return new NextResponse("RELAY_SECRET is not configured.", {
      status: 500,
      headers: { "Content-Type": "text/plain; charset=utf-8" },
    });
  }

  const installationId = request.nextUrl.searchParams.get("installation_id");
  const setupAction = request.nextUrl.searchParams.get("setup_action");
  const state = request.nextUrl.searchParams.get("state");

  if (!state) {
    return badRequest("Missing state parameter.");
  }

  const decoded = parseRelayInstallState(state, secret);
  if (!decoded) {
    return badRequest("Invalid or tampered state.");
  }

  if (!isValidInstanceUrl(decoded.instanceUrl)) {
    return badRequest("Invalid instance URL in state.");
  }

  const target = new URL("/api/auth/github/callback", decoded.instanceUrl.trim().replace(/\/+$/, ""));
  target.searchParams.set("state", state);
  if (installationId !== null) target.searchParams.set("installation_id", installationId);
  if (setupAction !== null) target.searchParams.set("setup_action", setupAction);

  return NextResponse.redirect(target.toString(), 302);
}

@import "tailwindcss";

@theme inline {
  --font-sans: var(--font-inter), ui-sans-serif, system-ui, sans-serif;
  --font-mono: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-border: var(--border);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-success: var(--success);
  --color-warning: var(--warning);
  --radius-lg: var(--radius);
}

/* Aligned with dashboard control-plane theme */
:root {
  --background: oklch(0.97 0.006 250);
  --foreground: oklch(0.22 0.04 260);
  --card: oklch(1 0 0);
  --card-foreground: oklch(0.22 0.04 260);
  --muted: oklch(0.955 0.012 250);
  --muted-foreground: oklch(0.46 0.02 260);
  --primary: oklch(0.48 0.2 255);
  --primary-foreground: oklch(0.99 0 0);
  --accent: oklch(0.93 0.04 255);
  --accent-foreground: oklch(0.28 0.08 260);
  --border: oklch(0.9 0.015 250);
  --success: oklch(0.55 0.14 155);
  --warning: oklch(0.72 0.14 75);
  --radius: 0.625rem;
}

body {
  background: var(--background);
  color: var(--foreground);
  font-family: var(--font-sans);
  -webkit-font-smoothing: antialiased;
}

@keyframes fade-up {
  from {
    opacity: 0;
    transform: translateY(12px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.animate-fade-up {
  animation: fade-up 0.5s ease-out both;
}

@keyframes pulse-dot {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.4;
  }
}

.animate-pulse-dot {
  animation: pulse-dot 2s ease-in-out infinite;
}

"use client";

import { useEffect, useRef, useState } from "react";

const LINES = [
  { text: "$ git push origin main", className: "text-foreground" },
  { text: "VersionGate ▸ webhook received", className: "text-primary" },
  { text: "VersionGate ▸ pulling source…              ✓", className: "text-success" },
  { text: "VersionGate ▸ building image…              ✓", className: "text-success" },
  { text: "VersionGate ▸ starting myapp-green…        ✓", className: "text-success" },
  { text: "VersionGate ▸ health check passed          ✓", className: "text-success" },
  { text: "VersionGate ▸ switching traffic → :3101    ✓", className: "text-success" },
  { text: "VersionGate ▸ stopping myapp-blue…         ✓", className: "text-success" },
  { text: "myapp-green is live  [v3 · ACTIVE · GREEN]", className: "text-foreground font-medium" },
];

export function TerminalDemo() {
  const [visible, setVisible] = useState<string[]>([]);
  const lineIdx = useRef(0);
  const charIdx = useRef(0);
  const current = useRef("");

  useEffect(() => {
    const tick = () => {
      const li = lineIdx.current;
      if (li >= LINES.length) return;

      const { text } = LINES[li];
      if (charIdx.current < text.length) {
        current.current += text[charIdx.current];
        charIdx.current += 1;
        setVisible((prev) => {
          const next = [...prev];
          next[li] = current.current;
          return next;
        });
      } else {
        lineIdx.current += 1;
        charIdx.current = 0;
        current.current = "";
        if (lineIdx.current < LINES.length) {
          setVisible((prev) => [...prev, ""]);
        }
      }
    };

    const id = window.setInterval(tick, 28);
    return () => window.clearInterval(id);
  }, []);

  return (
    <div className="overflow-hidden rounded-xl border border-border bg-[#0f1419] font-mono text-[13px] leading-relaxed shadow-lg">
      <div className="flex items-center gap-2 border-b border-white/10 px-4 py-2.5">
        <span className="size-2.5 rounded-full bg-red-500/80" />
        <span className="size-2.5 rounded-full bg-amber-400/80" />
        <span className="size-2.5 rounded-full bg-emerald-500/80" />
        <span className="ml-2 text-xs text-white/40">deploy.log</span>
      </div>
      <div className="min-h-[220px] space-y-1 p-4">
        {visible.map((line, i) => (
          <div key={i} className={LINES[i]?.className ?? "text-white/70"}>
            {line}
            {i === visible.length - 1 && lineIdx.current < LINES.length && (
              <span className="ml-0.5 inline-block h-3.5 w-2 animate-pulse bg-primary/80" />
            )}
          </div>
        ))}
      </div>
    </div>
  );
}

